import sqlite3
import stripe
from langchain_core.tools import tool
HOURLY_RATE_CENTS = 9500

@tool
def buy_sprint_contractor_hours(sprint_id: str, hours: int) -> dict:
    conn = sqlite3.connect('projects.db')
    row = conn.execute('SELECT billing_customer_id, budget_cents, purchased_hours FROM sprints WHERE id = ?', (sprint_id,)).fetchone()
    conn.close()
    if row is None:
        return {'status': 'error', 'message': f'Sprint {sprint_id} not found'}
    customer_id, budget_cents, purchased = row
    amount = hours * HOURLY_RATE_CENTS
    if amount > budget_cents:
        return {'status': 'error', 'message': 'Purchase exceeds sprint budget', 'amount_cents': amount}
    charge = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, description=f'Contractor hours for sprint {sprint_id}')
    conn = sqlite3.connect('projects.db')
    conn.execute('UPDATE sprints SET purchased_hours = purchased_hours + ?, budget_cents = budget_cents - ? WHERE id = ?', (hours, amount, sprint_id))
    conn.commit()
    conn.close()
    return {'status': charge.status, 'charge_id': charge.id, 'amount_cents': amount, 'total_purchased_hours': purchased + hours}
